// Generated by the daemon's tests from its Rust types (contract.rs): do not edit.
// To rewrite it: ATLAS_UPDATE_CONTRACT=1 cargo test -p atlas-daemon contract_types

export type Language = "fr" | "en";

/**
 * Body of `POST /api/language`: the language the master picks for the whole factory.
 */
export type LanguageInput = { language: Language, };

export type AgentStatus = "working" | "waiting" | "blocked" | "done";

export type StepState = "upcoming" | "current" | "done" | "skipped" | "external";

/**
 * Tokens a step consumed, read from the Claude Code transcripts of its sessions.
 */
export type StepUsage = { inputTokens: number, outputTokens: number, cacheReadTokens: number, cacheWriteTokens: number, };

/**
 * One step of an agent's own workflow: a brick of the catalogue, with what it cost.
 */
export type AgentStepView = { id: string, brickId: string, name: string, state: StepState, 
/**
 * Review pass, 1 for anything that is not a repeated review.
 */
pass: number, model: string, startedAt: string | null, endedAt: string | null, 
/**
 * Milliseconds spent waiting for the master during the step.
 */
waitMs: number, usage: StepUsage | null, };

export type AgentReport = { 
/**
 * Name of the step that wrote it.
 */
stepName: string, markdown: string, writtenAt: string, };

export type AgentView = { id: string, ticketRef: string, title: string, 
/**
 * Name of the project the agent works in: the declared one, else the repository folder.
 */
repoName: string, repoPath: string, worktreePath: string, branch: string, 
/**
 * Names of the other projects the agent also works in, each in a worktree on the same branch.
 */
extraRepos: Array<string>, 
/**
 * Brick of the current step.
 */
stepId: string, 
/**
 * The agent's workflow, in order: what it went through, where it is, what remains.
 */
steps: Array<AgentStepView>, status: AgentStatus, statusReason: string | null, 
/**
 * ISO date the agent entered its current step.
 */
stepStartedAt: string, 
/**
 * ISO date the agent started waiting, none when not waiting.
 */
waitingSince: string | null, mrUrl: string | null, 
/**
 * Session currently attached to the agent's terminal, none when closed.
 */
liveSessionId: string | null, 
/**
 * Latest rendering written for the master, shown without reopening the session.
 */
report: AgentReport | null, createdAt: string, updatedAt: string, };

export type SessionView = { id: string, agentId: string, 
/**
 * Session group of the brick the session was opened for.
 */
group: string, model: string, 
/**
 * Brick the session was opened for.
 */
stepId: string, startedAt: string, endedAt: string | null, outcome: string | null, };

export type MessageKind = "text" | "launch" | "decision" | "workflow";

export type CardStep = { name: string, state: StepState, };

/**
 * What a launch, decision or workflow message shows besides its reason.
 */
export type MessageCard = { ticketRef: string, steps: Array<CardStep>, };

/**
 * A change to the master's catalogue in `~/.atlas`, proposed by the orchestrator and applied only
 * once the master validates it.
 */
export type CatalogueChange = { "type": "brick", id: string, content: string, } | { "type": "skill", name: string, files: { [key in string]: string }, } | { "type": "subagent", name: string, content: string, } | { "type": "disable", id: string, } | { "type": "enable", id: string, };

/**
 * What the master made of a change to the catalogue the orchestrator proposed.
 */
export type CatalogueDecision = "applied" | "refused";

/**
 * Body of `POST /api/messages/:id/catalogue-change`: the master's decision on the change the message proposes.
 */
export type CatalogueDecisionInput = { decision: CatalogueDecision, };

/**
 * What the master can do straight from a message: the buttons under it.
 */
export type MessageAction = { "type": "session" } | { "type": "link", label: string, url: string, } | { "type": "resume" } | { "type": "archive" } | { "type": "save-note", repo: string | null, note: string, } | { "type": "apply-catalogue-change", change: CatalogueChange, decision: CatalogueDecision | null, };

export type MessageRole = "user" | "assistant";

export type ChatMessage = { id: string, role: MessageRole, kind: MessageKind, 
/**
 * The message itself; for a card, the reason the orchestrator gave.
 */
text: string, card: MessageCard | null, 
/**
 * Buttons to offer under the message, in order; they act on `agent_id`.
 */
actions: Array<MessageAction>, agentId: string | null, createdAt: string, };

export type BrickSummary = { id: string, name: string, };

export type Snapshot = { 
/**
 * The language the daemon speaks, which the page speaks too.
 */
language: Language, 
/**
 * The catalogue, for the names of the steps.
 */
bricks: Array<BrickSummary>, 
/**
 * Agents on the board: archived ones are left out.
 */
agents: Array<AgentView>, 
/**
 * Messages of the current conversation, since the last reset.
 */
messages: Array<ChatMessage>, 
/**
 * True while the orchestrator is thinking, so a client that connects mid-run shows it.
 */
orchestratorBusy: boolean, };

/**
 * Messages pushed on `GET /ws`.
 */
export type ServerEvent = { "type": "snapshot", snapshot: Snapshot, } | { "type": "agent", agent: AgentView, } | { "type": "archived", agentId: string, } | { "type": "message", message: ChatMessage, } | { "type": "orchestrator", busy: boolean, } | { "type": "reset" };

/**
 * Messages pushed on `GET /ws/terminal/:agentId`.
 */
export type TerminalServerEvent = { "type": "output", data: string, } | { "type": "exit", code: number | null, };

/**
 * Messages the terminal of the page sends on `GET /ws/terminal/:agentId`.
 */
export type TerminalClientEvent = { "type": "input", data: string, } | { "type": "resize", cols: number, rows: number, };

/**
 * Answer of `GET /api/health`.
 */
export type DaemonHealth = { name: string, version: string, };

/**
 * A project Atlas can launch agents in.
 */
export type RepoView = { name: string, path: string, 
/**
 * Ticket prefixes that belong to this project: `CAIRN` sends `CAIRN-123` here.
 */
ticketPrefixes: Array<string>, 
/**
 * Branch new work starts from, fetched from origin first; none means the branch checked out.
 */
baseBranch: string | null, 
/**
 * The project's memory: what the master taught an agent once and every later agent should know.
 */
notes: Array<string>, 
/**
 * Shell command that installs the dependencies, run in each worktree Atlas creates.
 */
setup: string | null, };

/**
 * What a client posts on `POST /api/messages`.
 */
export type PostMessageInput = { text: string, broadcast: boolean, 
/**
 * Ids of the agents mentioned with @ in the message; the orchestrator gets their context.
 */
mentions: Array<string>, };

/** Lines of history the daemon keeps for a session's terminal. */
export const TERMINAL_SCROLLBACK_LINES = 5000;
